codeExample.bad:
/* Fixed-width layout: at desktop widths this looks fine, but at a 320px
   viewport the 960px main content area doesn't shrink, so the user must
   scroll horizontally AND vertically just to read the article text. */
.page-layout {
  display: flex;
  width: 960px;
}
.page-layout__sidebar {
  width: 240px;
}
.page-layout__content {
  width: 720px;
}

codeExample.good:
/* Fluid layout with a breakpoint: the flex container and children use
   relative widths, and a media query stacks the sidebar below the content
   on narrow viewports, so the page reflows to one column and only ever
   needs vertical scrolling. */
.page-layout {
  display: flex;
  flex-wrap: wrap;
  width: 100%;
  max-width: 960px;
}
.page-layout__sidebar {
  flex: 1 1 240px;
}
.page-layout__content {
  flex: 3 1 480px;
}
@media (max-width: 480px) {
  .page-layout__sidebar,
  .page-layout__content {
    flex-basis: 100%;
  }
}
